prompt --application/shared_components/security/authentications/custom
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(168110674300056891459)
,p_name=>'CUSTOM'
,p_static_id=>'custom'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'user_aut',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION user_aut    (',
'    ',
' p_username IN VARCHAR2, --User_Name',
' p_password IN VARCHAR2 -- Password    ',
')',
' RETURN BOOLEAN',
'AS',
' lc_pwd_exit VARCHAR2 (1);',
'BEGIN',
' -- Validate whether the user exits or not',
' SELECT ''Y''',
' INTO lc_pwd_exit',
' FROM GS_USER',
' WHERE upper(user_name) = UPPER (P_username) AND u_password = p_password',
' AND STATUS = ''Y'';',
'RETURN TRUE;',
'EXCEPTION',
' WHEN NO_DATA_FOUND',
' THEN',
' RETURN FALSE;',
'END user_aut;'))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'15768250870699'
,p_created_on=>wwv_flow_imp.dz('20260512051009Z')
,p_updated_on=>wwv_flow_imp.dz('20260512100204Z')
,p_created_by=>'INNOCENTALEEZ@GMAIL.COM'
,p_updated_by=>'INNOCENTALEEZ@GMAIL.COM'
);
end;
