wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(168485512074917829644)
,p_plug_name=>'Current Stock of Diamond '
,p_static_id=>'current-stock-of-diamond_1'
,p_region_template_options=>'#DEFAULT#:t-Region--accent6:t-Region--stacked:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html CLOB;',
'BEGIN',
'    l_html := ''<div class="main-container">'';',
'',
'    FOR i IN (',
'        SELECT ',
'            gt.TYPE_NAME AS card_title,',
'',
'            (',
'                SELECT gs.CATAGORY_NAME',
'                FROM GS_GOLD_CATAGORY gs',
'                WHERE gs.CATAGORY_ID = gt.CATAGORY_ID',
'            ) AS card_subtitle,',
'',
'            NVL(',
'                GS_GET_CURRENT_STOCK(',
'                    gt.TYPE_ID,',
'                    :GS_COMPANY,',
'                    :GS_BRANCH',
'                ),',
'                0',
'            ) AS card_text,',
'',
'            ''u-color-2'' AS card_color,',
'',
'            gt.TYPE_ID AS card_id',
'',
'        FROM GS_GOLD_CATAGORY_TYPE gt',
'',
'        WHERE gt.CATAGORY_ID = 3',
'',
'        ORDER BY gt.CATAGORY_ID,',
'                 gt.TYPE_NAME',
'    )',
'    LOOP',
'',
'        l_html := l_html || ''',
'',
'            <div class="flip-container">',
'',
'                <div class="flipper">',
'',
'                    <div class="front '' || i.card_color || ''">',
'',
'                        <h2 class="front-title">',
'                            '' || i.card_title || ''',
'                        </h2>',
'',
'                        <p class="front-subtitle">',
'                            '' || i.card_subtitle || ''',
'                        </p>',
'',
'                    </div>',
'',
'                    <div class="back">',
'',
'                        <div class="back-detail-container">',
'',
'                            <h3 class="back-title">',
'                                '' || i.card_title || ''',
'                            </h3>',
'',
'                            <p class="back-subtitle">',
'                                '' || i.card_subtitle || ''',
'                            </p>',
'',
'                            <hr />',
'',
'                            <p class="stock-text">',
'                                Stock: '' || i.card_text || ''',
'                            </p>',
'',
'                        </div>',
'',
'                    </div>',
'',
'                </div>',
'',
'            </div>',
'',
'        '';',
'',
'    END LOOP;',
'',
'    l_html := l_html || ''</div>'';',
'',
'    RETURN l_html;',
'',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20260520050317Z')
,p_updated_on=>wwv_flow_imp.dz('20260520050318Z')
,p_created_by=>'INNOCENTALEEZ@GMAIL.COM'
