,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_html clob;',
'begin',
'    l_html := ''<div class="main-container">'';',
'',
'    for i in (',
'        select gt.TYPE_NAME as card_title, ',
'               (select CATAGORY_NAME ',
'                  from GS_GOLD_CATAGORY gs ',
'                 where gs.CATAGORY_ID = gt.CATAGORY_ID) as card_subtitle, ',
'               ',
'               NVL((',
'                   select GS_GET_CURRENT_STOCK(gt.TYPE_ID, :GS_COMPANY, :GS_BRANCH)',
'                   from dual',
'               ), 0) as card_text,',
'',
'               ''u-color-2'' as card_color,',
'               TYPE_ID as card_id',
'          from GS_GOLD_CATAGORY_TYPE gt',
'         where catagory_id = 1',
'         order by gt.CATAGORY_ID, gt.TYPE_NAME',
'    ) loop',
'',
'        l_html := l_html || ''',
'            <div class="flip-container">',
'                <div class="flipper">',
'                    ',
'                    <div class="front ''|| i.card_color ||''">',
'                        <h2 class="front-title">''|| i.card_title ||''</h2>',
'                        <p class="front-subtitle">''|| i.card_subtitle ||''</p>',
'                    </div>',
'',
'                    <div class="back">',
'                        <div class="back-detail-container">',
'                            <h3 class="back-title">''|| i.card_title ||''</h3>',
'                            <p class="back-subtitle">''|| i.card_subtitle ||''</p>',
'                            <hr />',
'                            <p class="stock-text">Stock: ''|| i.card_text ||''</p>',
'                        </div>',
'                    </div>',
'',
'                </div>',
'            </div>',
'        '';',
'',
'    end loop;',
'',
'    l_html := l_html || ''</div>'';',
'',
'    -- CRITICAL CHANGE: apex_util.prn ki jagah RETURN use karein',
'    return l_html; ',
'end;'))
