'SELECT ''Catagory: '' || (SELECT CATAGORY_NAME FROM GS_GOLD_CATAGORY GL WHERE GL.CATAGORY_ID = PI.CATAGORY_ID) AS CARD_SUBTITLE,',
'     ''Catagory Type: '' || (SELECT TYPE_NAME FROM GS_GOLD_CATAGORY_TYPE GL WHERE GL.TYPE_ID = PI.TYPE_ID) AS CARD_TEXT,',
'       (SELECT SUPPLIER_NAME FROM GS_SUPPLIER GS WHERE GS.SUPPLIER_ID = GP.SUPPLIER_ID) AS CARD_TITLE,',
'       ''Total QTY: ''||PI.QUANTITY||'' & Unit Price: ''||PI.UNITPRICE ||'' & Total Amount: '' ||PI.TOTALPRICE AS CARD_SUBTEXT,',
'       ''fa-user'' card_icon',
'    FROM  GS_PURCHASE GP,GS_PURCHASE_ITEM PI',
'          WHERE  GP.PURCHASE_ID =PI.PURCHASE_ID',
'          ORDER BY CATAGORY_ID'))
