,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Catagory: '' || (SELECT CATAGORY_NAME FROM GS_GOLD_CATAGORY GL WHERE GL.CATAGORY_ID = PI.CATAGORY_ID) AS CARD_SUBTITLE,',
'     ''Catagory Name : '' || (SELECT TYPE_NAME FROM GS_GOLD_CATAGORY_TYPE GL WHERE GL.TYPE_ID = PI.TYPE_ID) AS CARD_TEXT,',
