wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(168262377544909147635)
,p_plug_name=>'Current Stock Level'
,p_static_id=>'current-stock-level'
,p_region_template_options=>'#DEFAULT#:t-Region--accent11:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>60
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT (SELECT CATAGORY_NAME FROM GS_GOLD_CATAGORY GC WHERE GC.CATAGORY_ID = GI.CATAGORY_ID) CATAGORY_ID,',
'(SELECT TYPE_NAME FROM GS_GOLD_CATAGORY_TYPE GT WHERE GT.TYPE_ID = GI.TYPE_ID) TYPE_ID,',
'SUM(GI.QUANTITY),',
'ITEM_DESCRIPTION,UNITPRICE,TOTALPRICE,',
'PURCHASE_DATE,',
'(SELECT SUPPLIER_NAME FROM GS_SUPPLIER SS WHERE SS.SUPPLIER_ID = GP.SUPPLIER_ID) SUPPLIER_ID',
' FROM GS_PURCHASE GP ,GS_PURCHASE_ITEM GI',
'WHERE GP.PURCHASE_ID = GI.PURCHASE_ID',
'AND GP.PURCHASE_DATE BETWEEN TO_DATE(:P3_FROM_DATE,''DD/MM/RRRR'') AND TO_DATE(:P3_TO_DATE,''DD/MM/RRRR'')',
' GROUP BY GI.CATAGORY_ID,GI.TYPE_ID,UNITPRICE,ITEM_DESCRIPTION,TOTALPRICE,PURCHASE_DATE,SUPPLIER_ID',
'',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P3_FROM_DATE,P3_TO_DATE'
