 p_id=>wwv_flow_imp.id(168323752316945187471)
,p_plug_name=>'Current Stock Level'
,p_static_id=>'current-stock-level'
,p_region_template_options=>'#DEFAULT#:t-Region--accent11:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>60
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    GC.CATAGORY_NAME,',
'    GT.TYPE_NAME,',
'    SUM(GI.QUANTITY) AS TOTAL_QTY,',
'    GI.ITEM_DESCRIPTION,',
'    GI.UNITPRICE,',
'    GI.TOTALPRICE,',
'    GP.SALE_DATE,',
'    SS.SUPPLIER_NAME',
'FROM GS_SALE GP',
'JOIN GS_SALE_ITEM GI ',
'    ON GP.SALE_ID = GI.SALE_ID',
'LEFT JOIN GS_GOLD_CATAGORY GC ',
'    ON GC.CATAGORY_ID = GI.CATAGORY_ID',
'LEFT JOIN GS_GOLD_CATAGORY_TYPE GT ',
'    ON GT.TYPE_ID = GI.TYPE_ID',
'LEFT JOIN GS_SUPPLIER SS ',
'    ON SS.SUPPLIER_ID = GP.SUPPLIER_ID',
'WHERE GP.SALE_DATE BETWEEN ',
'    TO_DATE(:P4_FROM_DATE,''DD/MM/RRRR'') ',
'    AND TO_DATE(:P4_TO_DATE,''DD/MM/RRRR'')',
'GROUP BY ',
'    GC.CATAGORY_NAME,',
'    GT.TYPE_NAME,',
'    GI.ITEM_DESCRIPTION,',
'    GI.UNITPRICE,',
'    GI.TOTALPRICE,',
'    GP.SALE_DATE,',
'    SS.SUPPLIER_NAME;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P4_FROM_DATE,P4_TO_DATE'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
