'begin',
' SELECT TO_CHAR(TOTAL_AMOUNT) INTO v_total_amount',
'   FROM GS_SALE',
'   WHERE SALE_ID = :P5_SALE_ID;  ',
'',
'',
' ',
'htp.p(''<style>',
'.invoice-box {',
'      width: 102mm;',
