'{',
'   ',
'    body {',
'        padding-top:0mm;',
'    }',
'  ',
'</style>'');',
'',
'',
'',
'htp.p(''<article class="invoice">',
'  <header class="header">',
'    ',
'   ',
'  </header>',
'',
'       '');',
'       htp.p(''<body>',
'       ',
'    <div class="invoice-box">',
'     <div id="mid">',
'      <div class="info"> ',
'        <table>',
'         <tbody>',
'             <center style="margin-top:-10px !important; ">',
'      <div style=" height: 55px;',
'  width: 65px;',
'  background: url(#APP_FILES#icons/download.png) no-repeat ;',
'  background-size: 78px 61px;',
'"></div>',
'            </center>',
'          <td style="font-size: 10px; color: black; "><b>Date:</b><b style="padding-left:4px;">''||to_char(sysdate,''DD-MON-YYYY HH:MI'')||''</b></td>',
'           <td style="text-align: right; color: black; font-size: 10px;"><span><b>Bill#:</b><b style="padding-left:3px; size:1rem;">''||:P5_SALE_ID||''</b></span></td>',
'     <tr class="danger">',
'        <td style="font-size: 10px; color: black; "><b style="font-size: 11px;">Customer Name:</b><b style="padding-left:5px; font-size:12px;">''||:P5_SUPPLIER_ID||''</b></td>',
'          ',
'        ',
'     </tr>',
'  </tbody>',
'</table>',
'      </div>',
'    </div>',
'        <table cellpadding="0" cellspacing="0">',
'          <tr class="heading" style="margin-top:-30px;">',
'                <td style="font-size:12px; color: black; ">',
'                    Item',
'                </td >',
'                 <td style="font-size:12px; color: black; ">',
'                    Qty',
'                </td>',
'                <td align="right" style="font-size:12px; color: black; ">',
'                    Price',
'                </td>',
'             <td align="right" style="font-size:12px; color: black; ">',
'                    Amt',
'                </td>',
'               ',
'            </tr>'');',
'        for x in  ',
'       (SELECT (SELECT CATAGORY_NAME FROM GS_GLOD_CATAGORY GC WHERE GC.CATAGORY_ID = GI.CATAGORY_ID) CATAGORY_ID,',
'(SELECT TYPE_NAME FROM GS_GLOD_CATAGORY_TYPE GT WHERE GT.TYPE_ID = GI.TYPE_ID) TYPE_ID,',
'(GI.QUANTITY) QTY,',
'UNITPRICE,TOTALPRICE,',
'(SELECT SUPPLIER_NAME FROM GS_SUPPLIER SS WHERE SS.SUPPLIER_ID = GP.SUPPLIER_ID) SUPPLIER_ID',
' FROM GS_SALE GP ,GS_SALE_ITEM GI',
'WHERE GP.SALE_ID = GI.SALE_ID',
'AND GP.SALE_ID =:P5_SALE_ID',
'            )',
'   ',
'     ',
'         loop   ',
'       ',
'                    htp.p(''<tbody> ',
'            <tr class="item" style="color: black; ">',
'                <td >',
'                  ''|| x.CATAGORY_ID||'' - ''||x.TYPE_ID||''',
'                </td>',
'                 <td>',
'                    ''|| x.QTY||''',
'                </td>',
'                <td align="right">',
'                   ''|| x.UNITPRICE||''',
'                </td>',
'                 <td align="right">',
'                   ''|| x.TOTALPRICE||''',
'                </td>',
'            </tr>'');',
'  end loop;',
'  ',
' htp.p('' <tr class="item cashTotal" style="color: black; ">',
'                <td>',
'                  <b> Total:''||:P8_DISCOUNT||''</b>',
'                </td>',
'                ',
'               ',
'                 <td>',
'                    ''||:P8_T_QTY||''',
'                </td>',
'                <td>',
'                    ',
'                </td>',
'                <td align="right">',
'                  ''||v_total_amount||''',
'                </td>',
'            </tr>',
'         ',
'           ',
'        </table> ',
'       <hr>',
'        <img src="https://api.qrserver.com/v1/create-qr-code/?size=1000x1000&data=''||:P5_SALE_ID||'',''||:P5_TOTAL_CASH||''"  ',
'  id="QR_IMG" width="100"   />',
'       <p style="font-size: 11px; text-align: center;   color: black;"><b>SS Jewellers</b></p>',
'        <p style="font-size: 11px; text-align: center; color: black; height: 0; margin-top:-5px; "><b><i class="fa fa-phone-square" style="margin-top:3px;"></i>: 0306-7217106</b></p>',
'        <p style="font-size: 11px; text-align: center; color: black; height: 0; margin-top:-4px; "><b><i class="fa fa-map-marker" style="margin-top:3px;"></i>: Rail Bazar Near clock Tower, Faisalabad</b></p>',
'        <p style="font-size: 11px; text-align: center; color: black; margin-top:-4px; "><b>Thank you for Choosing SS Jewellers!</b></p>',
'    </div>',
'</body> '');',
' ',
'  end;',
'  '))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
);
