,p_static_id=>'company-branches'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'   case :APEX$ROW_STATUS ',
'   when ''C'' then ',
'     insert into GS_COMPANY_BRANCHES (Company_ID,Branch_Name,Address,City,State,Country,Postal_Code,Phone_Number,Email) ',
'     values ',
'     (:P7_COMPANY_ID,:Branch_Name,:Address,:City,:State,:Country,:Postal_Code,:Phone_Number,:Email); ',
'     commit;',
'   when ''U'' then  ',
'       update GS_COMPANY_BRANCHES  ',
'          set Branch_Name  = :Branch_Name, ',
'          Address = :Address,',
'          City = :City,',
'           State = :State,',
'           Country = :Country,',
'           Postal_Code = :Postal_Code,',
'           Phone_Number = :Phone_Number,',
'           Email  = :Email',
'          where Branch_ID = :Branch_ID; ',
'   when ''D'' then  ',
'       delete from GS_COMPANY_BRANCHES ',
'    where Branch_ID = :Branch_ID;',
'   end case;  ',
'end; '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
