'begin',
'   case :APEX$ROW_STATUS ',
'   when ''C'' then ',
'     insert into GS_GLOD_CATAGORY_TYPE (CATAGORY_ID,TYPE_NAME,DESCRIPTION,GS_COMP_ID,GS_BRANCH_ID) ',
'     values ',
'     (:P13_CATAGORY_ID,:TYPE_NAME,:DESCRIPTION,:GS_COMP_ID,:GS_BRANCH_ID); ',
'     commit;',
'   when ''U'' then  ',
'       update GS_GLOD_CATAGORY_TYPE  ',
'          set TYPE_NAME  = :TYPE_NAME, ',
'          DESCRIPTION = :DESCRIPTION',
'          where TYPE_ID = :TYPE_ID; ',
'   when ''D'' then  ',
'       delete from GS_GLOD_CATAGORY_TYPE ',
'    where TYPE_ID = :TYPE_ID;',
'   end case;  ',
'end; '))
