,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select PURCHASE_ID,',
'       (SELECT SUPPLIER_NAME FROM GS_SUPPLIER GS WHERE GS.SUPPLIER_ID = GP.SUPPLIER_ID) SUPPLIER_ID,',
'       PURCHASE_DATE,',
'       TOTAL_AMOUNT,',
'       DECODE(PAYMENT_STATUS,1,''Active'',0,''Inactive'',PAYMENT_STATUS) PAYMENT_STATUS,',
'       GS_COMPANY_ID,',
'       GS_BRANCH_ID,',
'       CREATED_DATE,',
'       CREATED_BY,',
'       UPDATED_DATE,',
'       UPDATED_BY',
'  from GS_PURCHASE GP',
'  WHERE GS_COMPANY_ID = :GS_COMPANY',
'  AND GS_BRANCH_ID = :GS_BRANCH'))
