,p_region_id=>wwv_flow_imp.id(168111401715011475624)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE PURCHASE ITEM DATA'
,p_static_id=>'save-purchase-item-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'   case :APEX$ROW_STATUS ',
'   when ''C'' then ',
'     insert into GS_PURCHASE_ITEM (PURCHASE_ID,CATAGORY_ID,TYPE_ID,ITEM_DESCRIPTION,QUANTITY,UNITPRICE,TOTALPRICE,GS_COMPANY_ID,GS_BARANCH_ID) ',
'     values ',
'     (:P23_PURCHASE_ID,:CATAGORY_ID,:TYPE_ID,:ITEM_DESCRIPTION,:QUANTITY,:UNITPRICE,:TOTALPRICE,:GS_COMPANY_ID,:GS_BARANCH_ID); ',
'     commit;',
'   when ''U'' then  ',
'       update GS_PURCHASE_ITEM  ',
'          set CATAGORY_ID  = :CATAGORY_ID, ',
'          TYPE_ID = :TYPE_ID,',
'          ITEM_DESCRIPTION = :ITEM_DESCRIPTION,',
'           QUANTITY = :QUANTITY,',
'           UNITPRICE = :UNITPRICE,',
'           TOTALPRICE = :TOTALPRICE',
'          where PURCHASE_ITEM_ID = :PURCHASE_ITEM_ID; ',
'   when ''D'' then  ',
'       delete from GS_PURCHASE_ITEM ',
'    where PURCHASE_ITEM_ID = :PURCHASE_ITEM_ID;',
'   end case;  ',
'end; '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_exec_cond_for_each_row=>'Y'
,p_internal_uid=>53820939099384710
);
