,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(168141017634310199505)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE DATA SALE ITEM '
,p_static_id=>'save-data-sale-item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'   case :APEX$ROW_STATUS ',
'   when ''C'' then ',
'     insert into GS_SALE_ITEM (SALE_ID,CATAGORY_ID,TYPE_ID,ITEM_DESCRIPTION,QUANTITY,UNITPRICE,TOTALPRICE,GS_COMPANY_ID,GS_BARANCH_ID) ',
'     values ',
'     (:P25_SALE_ID,:CATAGORY_ID,:TYPE_ID,:ITEM_DESCRIPTION,:QUANTITY,:UNITPRICE,:TOTALPRICE,:GS_COMPANY_ID,:GS_BARANCH_ID); ',
'     commit;',
'   when ''U'' then  ',
'       update GS_SALE_ITEM  ',
'          set CATAGORY_ID  = :CATAGORY_ID, ',
'          TYPE_ID = :TYPE_ID,',
'          ITEM_DESCRIPTION = :ITEM_DESCRIPTION,',
'           QUANTITY = :QUANTITY,',
'           UNITPRICE = :UNITPRICE,',
'           TOTALPRICE = :TOTALPRICE',
'          where SALE_ITEM_ID = :SALE_ITEM_ID; ',
'   when ''D'' then  ',
'       delete from GS_SALE_ITEM ',
'    where SALE_ITEM_ID = :SALE_ITEM_ID;',
'   end case;  ',
'end; '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_exec_cond_for_each_row=>'Y'
,p_internal_uid=>53823975477384740
);
