,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID,',
'       DECODE(ROLE_ID,1,''Admin'',2,''User'',ROLE_ID) AS ROLE_ID,',
'       (select PAGE_NAME from apex_application_pages A WHERE A.PAGE_ID = R.PAGE_ID AND APPLICATION_ID = :APP_ID) PAGE_ID,',
